<script setup>
import AppShell from '../../Layouts/AppShell.vue';import PageHeader from '../../Components/PageHeader.vue';import SettingsNav from '../../Components/SettingsNav.vue';import StateCard from '../../Components/StateCard.vue';import UiAlert from '../../Components/UiAlert.vue';import UiBadge from '../../Components/UiBadge.vue';import PlanFeatureIcon from '../../Components/PlanFeatureIcon.vue';import {Head} from '@inertiajs/vue3';import {computed,ref} from 'vue'
const p=defineProps({user:Object,currentSubscription:Object,subscriptions:Array,orders:Array,availablePlans:Array,paymentConfigured:Boolean,usage:Object,billingMode:String}),cycle=ref(p.currentSubscription?.billing_cycle||'quarterly'),selected=ref(null),busy=ref(false),status=ref(''),error=ref(''),accepted=ref(false)
const money=(v,c='INR')=>new Intl.NumberFormat('en-IN',{style:'currency',currency:c}).format(Number(v||0)/100),date=v=>v?new Date(v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Not scheduled',rank=computed(()=>p.availablePlans.find(x=>x.code===p.currentSubscription?.plan)?.rank||0),price=computed(()=>selected.value?.cycles.find(x=>x.cycle===cycle.value))
const planPrice=x=>x.cycles.find(y=>y.cycle===cycle.value)
function cta(x){if(x.code===p.currentSubscription?.plan)return'Current Plan';if(!p.currentSubscription)return'Get Started';return x.rank>rank.value?`Upgrade to ${x.name}`:'Switch at Renewal'}
function saving(x){let q=x.cycles.find(y=>y.cycle==='quarterly')?.base_amount||0,a=x.cycles.find(y=>y.cycle==='yearly')?.base_amount||0;return Math.max(0,q*4-a)}
function choose(x){if(x.code!==p.currentSubscription?.plan&&!busy.value){selected.value=x;accepted.value=false;requestAnimationFrame(()=>document.querySelector('#plan-review')?.focus())}}
function load(){return new Promise((ok,no)=>{if(window.Razorpay)return ok();let s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=ok;s.onerror=no;document.head.appendChild(s)})}
function verify(data){let f=document.createElement('form');f.method='POST';f.action='/billing/razorpay/verify';f.hidden=true;for(const[k,v]of Object.entries({_token:document.querySelector('meta[name="csrf-token"]')?.content||'',...data})){let i=document.createElement('input');i.name=k;i.value=v;f.appendChild(i)}document.body.appendChild(f);f.submit()}
async function checkout(){if(!selected.value||!accepted.value||busy.value)return;busy.value=true;status.value='Preparing secure checkout…';error.value='';try{let r=await fetch('/billing/razorpay/order',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''},body:JSON.stringify({plan:selected.value.code,cycle:cycle.value})}),d=await r.json();if(!r.ok)throw d;await load();status.value='';new window.Razorpay({...d,name:d.display_name,image:d.logo_url||undefined,handler:x=>{status.value='Verifying payment…';verify(x)},modal:{ondismiss:async()=>{busy.value=false;status.value='Payment was cancelled. No amount was charged by LensPic.';if(d.cancel_url)await fetch(d.cancel_url,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''}})}}}).open()}catch(e){busy.value=false;status.value='';error.value=e.message||'We couldn’t complete your payment. Please try again or use another payment method.'}}
async function scheduleFree(){if(busy.value)return;busy.value=true;let r=await fetch('/billing/subscription/schedule-free',{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||''}}),d=await r.json();busy.value=false;if(r.ok){status.value=d.message;p.currentSubscription.scheduled_plan='free'}else error.value=d.message||'The plan change could not be scheduled.'}
</script>
<template><AppShell><Head title="Plans & Subscription"/><div class="lp-page"><PageHeader eyebrow="Studio settings" title="Plans & Subscription" description="Compare authoritative plan limits and complete verified payment securely."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav section="subscription"/><main class="min-w-0 space-y-6" aria-live="polite"><UiAlert v-if="billingMode==='test'" tone="warning">Test Payment Mode is active.</UiAlert><UiAlert v-if="error" tone="error">{{error}}</UiAlert><UiAlert v-if="status">{{status}}</UiAlert>
<section class="lp-card p-6"><div class="flex flex-wrap justify-between gap-4"><div><p class="eyebrow">Current subscription</p><h2 class="mt-2 text-3xl font-bold">{{user.plan_label}}</h2><p class="mt-2 capitalize text-slate-600">{{currentSubscription?.status||'Free'}}</p></div><UiBadge :tone="currentSubscription?'success':'warning'">{{currentSubscription?'Active':'Free'}}</UiBadge></div><dl class="mt-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div><dt>Billing interval</dt><dd class="font-semibold capitalize">{{currentSubscription?.billing_cycle||'None'}}</dd></div><div><dt>Activated</dt><dd class="font-semibold">{{date(currentSubscription?.starts_at)}}</dd></div><div><dt>Renewal / expiry</dt><dd class="font-semibold">{{date(currentSubscription?.expires_at||user.plan_expires_at)}}</dd></div><div><dt>Storage</dt><dd class="font-semibold">{{user.storage_used_human}} / {{user.plan_limits.storage_label}}</dd></div><div><dt>Stored photo quota</dt><dd class="font-semibold">{{usage.storage.used_quota_units}} / {{usage.storage.limits.photo_limit.toLocaleString()}}</dd></div><div><dt>Video quota</dt><dd class="font-semibold">{{usage.storage.video_storage_used_mb}} / {{usage.storage.limits.video_storage_limit_mb.toLocaleString()}} MB</dd></div><div><dt>Team seats</dt><dd class="font-semibold">{{usage.team.used}} / {{usage.team.unlimited?'Unlimited':usage.team.limit}}</dd></div><div><dt>Auto-renewal</dt><dd class="font-semibold">Not enabled</dd></div></dl></section>
<section class="lp-card p-6"><div class="flex flex-wrap justify-between gap-4"><div><h2 class="text-xl font-bold">Available plans</h2><p class="lp-subtitle">Base prices, GST and checkout totals come from one plan catalog.</p></div><div class="flex rounded-xl bg-slate-100 p-1" role="group" aria-label="Billing interval"><button v-for="term in ['quarterly','yearly']" :key="term" :aria-pressed="cycle===term" :class="['rounded-lg px-4 py-2 font-semibold capitalize',cycle===term?'bg-white text-indigo shadow':'']" @click="cycle=term">{{term==='yearly'?'Yearly':'Quarterly'}}</button></div></div><UiAlert v-if="!paymentConfigured" tone="warning" class="mt-5">Checkout is not configured.</UiAlert><div v-if="cycle==='yearly'" class="mt-4 text-sm font-semibold text-emerald-700">Annual savings are calculated from four quarterly terms using the configured base prices.</div><div class="mt-6 grid items-stretch gap-6 md:grid-cols-2 xl:grid-cols-4" role="list" aria-label="Subscription plans"><article v-for="x in availablePlans" :key="x.code" data-plan-card :data-plan-code="x.code" :class="['flex h-full min-w-0 flex-col rounded-xl border p-5',x.code===currentSubscription?.plan?'border-indigo ring-2 ring-indigo/20':'border-slate-200']" role="listitem"><div class="flex flex-1 flex-col"><h3 class="text-xl font-bold">{{x.name}}</h3><p class="mt-2 text-sm text-slate-600">{{x.description}}</p><p class="mt-4 text-2xl font-bold">{{money(planPrice(x).base_amount)}} <span class="text-sm font-semibold text-slate-500">+ GST</span></p><p class="mt-1 text-xs text-slate-500">{{money(planPrice(x).base_amount)}} base + {{money(planPrice(x).gst_amount)}} GST · /{{cycle==='yearly'?'year':'quarter'}}</p><p class="mt-1 text-xs font-semibold text-slate-700">Total payable {{money(planPrice(x).total_amount)}}</p><UiBadge v-if="cycle==='yearly'&&saving(x)>0" tone="success" class="mt-2">Save {{money(saving(x))}} annually</UiBadge><div class="my-5 space-y-2 text-sm"><p class="flex items-start gap-2 font-bold"><span class="mt-0.5 h-5 w-5 flex-none text-indigo"><PlanFeatureIcon name="images"/></span><span class="min-w-0">Store up to {{x.entitlements.photo_limit.toLocaleString()}} photos</span></p><p v-if="x.entitlements.video_storage_limit_mb>0" class="flex items-start gap-2"><span class="mt-0.5 h-5 w-5 flex-none text-indigo"><PlanFeatureIcon name="video"/></span><span class="min-w-0">Store up to {{x.entitlements.video_storage_limit_mb/1000}} GB of videos</span></p><p v-if="x.entitlements.photo_delete_reupload_limit>x.entitlements.photo_limit" class="flex items-start gap-2"><span class="mt-0.5 h-5 w-5 flex-none text-indigo"><PlanFeatureIcon name="refresh"/></span><span class="min-w-0">Reuse up to {{x.entitlements.photo_delete_reupload_limit.toLocaleString()}} photos</span></p><ul class="mt-4 space-y-2"><li v-for="f in x.features" :key="f.label" class="flex items-start gap-2"><span class="mt-0.5 h-5 w-5 flex-none text-indigo"><PlanFeatureIcon :name="f.icon"/></span><span class="min-w-0">{{f.label}}</span></li></ul><div v-for="addon in x.optional_addons" :key="addon.name" class="mt-4 flex items-start gap-2 rounded-lg border border-amber-200 bg-amber-50 p-3 text-amber-900"><span class="mt-0.5 h-5 w-5 flex-none"><PlanFeatureIcon name="plus-circle"/></span><span class="min-w-0"><strong class="block text-xs uppercase tracking-wide">Optional add-on</strong>{{addon.name}} — {{money(addon.base_amount)}} + GST</span></div></div></div><div class="mt-auto pt-6"><button :class="[x.code===currentSubscription?.plan?'btn-secondary':'btn-primary','flex min-h-11 w-full items-center justify-center']" :disabled="busy||!paymentConfigured||x.code===currentSubscription?.plan" @click="choose(x)"><span v-if="x.code===currentSubscription?.plan" class="mr-2 h-5 w-5 flex-none" aria-hidden="true"><PlanFeatureIcon name="check-circle"/></span>{{cta(x)}}</button></div></article></div><a href="/pricing" class="mt-5 inline-block font-semibold text-indigo underline">View complete feature comparison</a></section>
<section class="lp-card grid gap-5 p-6 md:grid-cols-2"><div><h2 class="text-xl font-bold">Free plan</h2><p class="mt-2 text-sm text-slate-600">Up to 3 Groups, 100 photos per Group and 1 GB storage. Paid-only quotas and studio capabilities are limited.</p><button v-if="currentSubscription" type="button" class="btn-secondary mt-4" :disabled="busy||currentSubscription.scheduled_plan==='free'" @click="scheduleFree">{{currentSubscription.scheduled_plan==='free'?'Free Plan Scheduled':'Switch to Free at Renewal'}}</button><a v-else href="/dashboard" class="btn-secondary mt-4 inline-flex">Continue with Free Plan</a><p v-if="currentSubscription" class="mt-2 text-xs text-slate-500">Your paid access remains active until expiry. Existing media is not deleted; future uploads may be restricted when usage exceeds Free limits.</p></div><div><h2 class="text-xl font-bold">Need more storage or custom features?</h2><p class="mt-2 text-sm text-slate-600">Talk with LensPic about requirements beyond the configured plans.</p><a href="/contact?type=Sales%20Enquiry" class="btn-primary mt-4 inline-flex">Contact Us</a></div></section>
<section v-if="selected" id="plan-review" tabindex="-1" class="lp-card p-6"><p class="eyebrow">Review selection</p><h2 class="mt-2 text-2xl font-bold">{{selected.name}} · <span class="capitalize">{{cycle}}</span></h2><dl class="mt-5 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div><dt>Base</dt><dd class="font-bold">{{money(price.base_amount)}}</dd></div><div><dt>GST ({{price.gst_basis_points/100}}%)</dt><dd class="font-bold">{{money(price.gst_amount)}}</dd></div><div><dt>Total payable</dt><dd class="font-bold">{{money(price.total_amount)}}</dd></div><div><dt>Current plan</dt><dd class="font-bold">{{user.plan_label}}</dd></div></dl><p class="mt-5 text-sm text-slate-600">This is a full new term. Renewal extends from the later of current expiry or verified payment; automatic renewal and proration are not enabled.</p><label class="mt-5 flex gap-3 text-sm"><input v-model="accepted" type="checkbox">I accept the <a href="/terms" class="text-indigo underline">Terms</a> and <a href="/refunds" class="text-indigo underline">Refund Policy</a>.</label><div class="mt-5 flex gap-3"><button class="btn-primary" :disabled="!accepted||busy" @click="checkout">{{busy?'Preparing secure checkout…':'Proceed to Secure Payment'}}</button><button class="btn-secondary" :disabled="busy" @click="selected=null">Back to Plans</button></div></section>
<section class="lp-card p-6"><h2 class="text-xl font-bold">Payment history</h2><StateCard v-if="!subscriptions.length&&!orders.length" class="mt-5" title="No billing history" message="Verified subscriptions and payment attempts appear here."/><div v-else class="lp-table-wrap mt-5"><table class="lp-table"><thead><tr><th>Date</th><th>Plan</th><th>Interval</th><th>Total</th><th>Status</th></tr></thead><tbody><tr v-for="s in subscriptions" :key="s.id"><td>{{date(s.created_at)}}</td><td class="capitalize">{{s.plan}}</td><td class="capitalize">{{s.billing_cycle}}</td><td>{{new Intl.NumberFormat('en-IN',{style:'currency',currency:s.currency}).format(s.amount)}}</td><td>{{s.status}}</td></tr><tr v-for="o in orders.filter(x=>x.status!=='paid')" :key="`o${o.id}`"><td>{{date(o.created_at)}}</td><td class="capitalize">{{o.plan}}</td><td>{{o.billing_cycle}}</td><td>{{money(o.amount,o.currency)}}</td><td>{{o.status}}</td></tr></tbody></table></div></section></main></div></div></AppShell></template>
